def max_elements(p):
    from functools import lru_cache

    @lru_cache(None)
    def split_count(num_str):
        if len(num_str) == 1:
            return 1

        max_count = 1
        for i in range(1, len(num_str)):
            left = num_str[:i]
            right = num_str[i:]
            if right[0] != '0' and int(left) >= int(right):
                max_count = max(max_count, 1 + split_count(left) + split_count(right))

        return max_count

    return split_count(str(p)) - 1

