    n = len(p_str)

    # dp[i] will store the maximum number of elements that can form p_str[:i]
    dp = [0] * (n + 1)
    dp[0] = 1  # Base case: an empty string can be formed by 0 elements

    # prev[i][j] will store the index of the last element used to form p_str[:i] ending with p_str[j]
    prev = [[-1] * 10 for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(10):
            if p_str[i - 1] == str(j):
                for k in range(i):
                    if p_str[k:i] == str(int(p_str[k:i]) // 10) + str(j):
                        if dp[k] + 1 > dp[i]:
                            dp[i] = dp[k] + 1
                            prev[i][j] = k

    # Reconstruct the maximum number of elements
    max_count = dp[n]
    current_index = n
    result = []

    while current_index > 0:
        for j in range(10):
            if prev[current_index][j] != -1:
                result.append(p_str[prev[current_index][j]:current_index])
                current_index = prev[current_index][j]
                break

    return max_count

