def max_elements(p):
    p_str = str(p)
    n = len(p_str)

    def can_form(p_str, i, j):
        if i > j:
            return False
        if i == j:
            return True
        if p_str[i] == '0':
            return False
        num1 = int(p_str[i:j+1])
        for k in range(i+1, j+1):
            num2 = int(p_str[k:j+1])
            if num1 >= num2 and str(num1) + str(num2) == p_str[i:j+1]:
                if can_form(p_str, i, k-1) and can_form(p_str, k, j):
                    return True
        return False

    def count_max_elements(p_str, i, j):
        if i > j:
            return 0
        if i == j:
            return 1
        if p_str[i] == '0':
            return 0
        num1 = int(p_str[i:j+1])
        max_count = 1
        for k in range(i+1, j+1):
            num2 = int(p_str[k:j+1])
            if num1 >= num2 and str(num1) + str(num2) == p_str[i:j+1]:
                count = 1 + count_max_elements(p_str, i, k-1) + count_max_elements(p_str, k, j)
                max_count = max(max_count, count)
        return max_count

    return count_max_elements(p_str, 0, n-1)

